/**
 * Shared runtime wiring used by both the CLI (dynamic scanning) and the
 * entry generated by `feed build`, so system resolution, config overrides,
 * and engine construction behave identically in dev and built modes.
 */

import { logger } from '@feed/shared';
import type { FeedRuntimeConfig } from './config';
import { FeedEngine } from './engine';
import { FrameworkError } from './errors';
import { type FeedSystem, TickPhase } from './types';

export function isFeedSystem(obj: unknown): obj is FeedSystem {
  if (!obj || typeof obj !== 'object') return false;
  const m = obj as Record<string, unknown>;
  return (
    typeof m.id === 'string' &&
    typeof m.name === 'string' &&
    typeof m.phase === 'number' &&
    typeof m.onTick === 'function'
  );
}

function isClassConstructor(value: unknown): value is new () => unknown {
  return (
    typeof value === 'function' &&
    /^class[\s{]/.test(Function.prototype.toString.call(value))
  );
}

/**
 * Resolve every FeedSystem exported by a module namespace.
 *
 * - Objects satisfying FeedSystem are used as-is.
 * - Class exports are instantiated; a throwing constructor fails with the
 *   export name and source file.
 * - Plain functions and other exports are ignored (never invoked).
 * - The same value exported under several names (e.g. default + named) is
 *   registered once.
 */
export function resolveModuleSystems(
  mod: Record<string, unknown>,
  source: string
): FeedSystem[] {
  const entries = Object.entries(mod).sort(([a], [b]) =>
    a === 'default' ? -1 : b === 'default' ? 1 : 0
  );
  const seenValues = new Set<unknown>();
  const systems: FeedSystem[] = [];

  for (const [name, value] of entries) {
    if (!value || seenValues.has(value)) continue;
    seenValues.add(value);

    if (isFeedSystem(value)) {
      systems.push(value);
      continue;
    }

    if (isClassConstructor(value)) {
      let instance: unknown;
      try {
        instance = new value();
      } catch (err) {
        const message = err instanceof Error ? err.message : String(err);
        throw new FrameworkError(
          `Failed to instantiate system class "${name}" from ${source}: ${message}`
        );
      }
      if (isFeedSystem(instance)) systems.push(instance);
    }
  }

  return systems;
}

const validPhases = new Set<number>(Object.values(TickPhase));

/**
 * Apply a configured phase override. Invalid overrides are ignored with a
 * warning. Frozen/readonly systems are wrapped, keeping every lifecycle hook
 * bound to the original instance.
 */
export function applyPhaseOverride(
  sys: FeedSystem,
  override: unknown
): FeedSystem {
  if (override === undefined) return sys;
  if (typeof override !== 'number' || !validPhases.has(override)) {
    logger.warn(
      `Ignoring invalid phase override for "${sys.id}": ${String(override)}`,
      undefined,
      'Runtime'
    );
    return sys;
  }
  const phase = override as TickPhase;
  if (sys.phase === phase) return sys;

  try {
    (sys as { phase: TickPhase }).phase = phase;
  } catch (err) {
    // Frozen or getter-only `phase` (strict-mode assignment TypeError).
    if (!(err instanceof TypeError)) throw err;
  }
  if (sys.phase === phase) return sys;

  const register = sys.register;
  const destroy = sys.destroy;
  return {
    id: sys.id,
    name: sys.name,
    phase,
    dependencies: sys.dependencies,
    skipDeadlineCheck: sys.skipDeadlineCheck,
    intervals: sys.intervals,
    register: register ? (ctx) => register.call(sys, ctx) : undefined,
    onTick: (ctx) => sys.onTick(ctx),
    destroy: destroy ? () => destroy.call(sys) : undefined,
  };
}

/** Create an engine whose EngineConfig is derived from the runtime config. */
export function createEngineFromConfig(config: FeedRuntimeConfig): FeedEngine {
  const {
    systemsDir: _systemsDir,
    disabledSystems: _disabledSystems,
    systemPhases: _systemPhases,
    migratedSubsystems: _migratedSubsystems,
    dev: _dev,
    ...customKeys
  } = config;
  return new FeedEngine({
    config: { budgetMs: config.budgetMs ?? 60_000, ...customKeys },
  });
}

/**
 * Register systems on an engine, honoring `disabledSystems` and
 * `systemPhases`. Returns the number of systems registered.
 */
export function registerSystems(
  engine: FeedEngine,
  systems: FeedSystem[],
  config: FeedRuntimeConfig
): number {
  const disabled = new Set(config.disabledSystems ?? []);
  const overrides: Record<string, unknown> = config.systemPhases ?? {};
  let registered = 0;
  for (const sys of systems) {
    if (disabled.has(sys.id)) {
      logger.warn(
        `System "${sys.id}" disabled by config`,
        undefined,
        'Runtime'
      );
      continue;
    }
    engine.use(applyPhaseOverride(sys, overrides[sys.id]));
    registered++;
  }
  return registered;
}
